insert into public.policies (id, title, policy_domain, version, abstract_en, abstract_hi, status, keywords, target_audience, lead_drafter, nep_thrust_areas, nep_alignment_justification, version_history)
values
  ('POL-TN-FLN-2026', 'Tamil Nadu Foundational Learning Assurance Framework', 'Curriculum & Pedagogy', '1.0', 'State policy draft for foundational literacy and numeracy assurance, classroom support, review evidence and accountable implementation through SCERT and district structures.', 'அடிப்படை எழுத்தறிவு மற்றும் எண்ணறிவு உறுதிப்படுத்தலுக்கான தமிழ்நாடு மாநிலக் கொள்கை வரைவு.', 'Pending Internal Review', array['FLN','NIPUN','Tamil Nadu'], array['State/UT Education Departments','District/Block/Cluster Education Authorities','Teachers & Educators'], 'SCERT Tamil Nadu', array['Foundational Literacy & Numeracy','Equitable & Inclusive Education'], 'Aligns implementation evidence, teacher support and human oversight with the foundational-learning thrust.', '[{"version":"1.0","status":"Pending Internal Review","summary":"Canonical live baseline","modified_at":"2026-07-28T00:00:00.000Z"}]'::jsonb),
  ('POL-TN-SAFE-2026', 'Whole-School Safety and Child Protection Standard', 'Governance & Administration', '1.0', 'State policy draft defining prevention, incident response, escalation, audit evidence and accountable human authority for child safety across government schools.', 'அரசுப் பள்ளிகளுக்கான குழந்தைப் பாதுகாப்பு மற்றும் பள்ளி முழுமையான பாதுகாப்புத் தரநிலை வரைவு.', 'Draft', array['POCSO','safety','audit'], array['School Administrators (Principals, Vice-Principals)','Teachers & Educators','Parents & Guardians'], 'Directorate of School Education', array['Robust Regulatory Framework','Equitable & Inclusive Education'], 'Establishes auditable safeguards and named human authority for every safety decision.', '[{"version":"1.0","status":"Draft","summary":"Canonical live baseline","modified_at":"2026-07-28T00:00:00.000Z"}]'::jsonb)
